sp_widget.client_script:
api.controller = function($scope) {
  var c = this;

  c.faqs = [
    {
      q: 'What is GateNow?',
      a: 'GateNow is a federal grant management platform that simplifies the entire grant lifecycle — from discovering open programs and confirming eligibility, to submitting compliant applications and tracking award status — all within a single secure, guided platform.'
    },
    {
      q: 'Who can apply for grants through GateNow?',
      a: 'GateNow is open to eligible applicants including state and local government agencies, tribal governments, transit authorities, metropolitan planning organizations (MPOs), and other public entities seeking federal transportation funding.'
    },
    {
      q: 'What types of projects are eligible for funding?',
      a: 'Eligible projects typically include transportation infrastructure improvements, highway safety enhancements, public transit expansions, climate resilience initiatives, and innovation projects aligned with federal transportation priorities under programs such as FHWA and FTA grant programs.'
    },
    {
      q: 'How do I apply for a grant?',
      a: 'Start by exploring available programs under the "Grant Programs" section. Once you find a program that matches your needs, confirm your eligibility, complete the guided application form, attach required documentation, and submit. GateNow will notify you of status updates at each stage.'
    },
    {
      q: 'Can I save my application and finish it later?',
      a: 'Yes. GateNow automatically saves your progress as you complete each section of the application. You can return at any time, pick up where you left off, and submit when you are ready before the program deadline.'
    },
    {
      q: 'How long does the grant review process take?',
      a: 'Review timelines vary by program and funding agency. Once you submit your application, GateNow will display the estimated review period for that specific program. You can monitor your application status in real time from your dashboard.'
    },
    {
      q: 'What documents are typically required?',
      a: 'Required documents vary by program but commonly include a project narrative, budget breakdown, organizational certifications, environmental review documentation, and proof of matching funds where applicable. Each program listing in GateNow specifies its exact requirements.'
    },
    {
      q: 'Is my data secure on GateNow?',
      a: 'Yes. GateNow is built on the ServiceNow platform which is FedRAMP-authorized and complies with federal security standards. All data is encrypted in transit and at rest, and access is controlled through role-based permissions.'
    }
  ];

  c.toggle = function(item) {
    item.open = !item.open;
  };
};

sp_widget.css:
/* ─── Reset ───────────────────────────────────────────── */
.faq-wrapper *,
.faq-wrapper *::before,
.faq-wrapper *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

/* ─── Outer wrapper ───────────────────────────────────── */
.faq-wrapper {
  font-family: 'Inter', 'Plus Jakarta Sans', 'Segoe UI', sans-serif;
  background: #f0f0f2;
  width: calc(100% + 30px);
  margin-left: -15px;
  margin-right: -15px;
   padding: 52px 0 60px; 
}

/* ─── Two-column inner ────────────────────────────────── */
.faq-inner {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 60px;
  display: grid;
  grid-template-columns: 340px 1fr;
  gap: 0 160px;
  align-items: start; 
}

/* ─── LEFT column ─────────────────────────────────────── */
.faq-left {
  display: flex;
  flex-direction: column;
  gap: 0;
  position: sticky;
  top: 100px;
}

.faq-eyebrow {
  font-size: 13px;
  font-weight: 500;
  color: #5443ad;
  letter-spacing: 0.01em;
  margin-bottom: 8px; 
}

.faq-rule {
  border: none;
  border-top: 1.5px solid #d1d5db;
  margin-bottom: 16px;
}

.faq-heading {
  font-size: 26px;
  font-weight: 700;
  line-height: 1.3;
  color: #0f172a;
 margin-bottom: 10px;
}

.faq-subtext {
  font-size: 13px;
  font-weight: 400;
  line-height: 1.65;
  color: #6b7280;
}

/* ─── RIGHT column: accordion ─────────────────────────── */
.faq-right {
  display: flex;
  flex-direction: column;
}

/* ─── Each FAQ item ───────────────────────────────────── */
.faq-item {
  border-bottom: 1px solid #d1d5db;
}

.faq-item:first-child {
  border-top: 1px solid #d1d5db;
}

/* ─── Question row ────────────────────────────────────── */
.faq-question {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  padding: 12px 0;
  background: none;
  border: none;
  cursor: pointer;
  text-align: left;
}

.faq-question-text {
  font-size: 12px;
  font-weight: 400;
  color: #1f2937;
  line-height: 1.5;
  transition: color 0.2s ease;
}

.faq-item--open .faq-question-text {
  color: #5443ad;
  font-weight: 500;
}

.faq-icon {
  font-size: 22px;
  font-weight: 300;
  color: #4b5563;
  line-height: 1;
  flex-shrink: 0;
  width: 24px;
  text-align: center;
  transition: color 0.2s ease, transform 0.2s ease;
}

.faq-item--open .faq-icon {
  color: #5443ad;
}

/* ─── Answer panel ────────────────────────────────────── */
.faq-answer {
  padding: 0 40px 20px 0;
}

.faq-answer p {
  font-size: 14px;
  font-weight: 400;
  line-height: 1.75;
  color: #6b7280;
}

/* ─── Responsive ──────────────────────────────────────── */
@media (max-width: 1024px) {
  .faq-inner { padding: 0 40px; gap: 0 48px; }
}

@media (max-width: 820px) {
  .faq-inner {
    grid-template-columns: 1fr;
    gap: 40px 0;
    padding: 0 32px;
  }
  .faq-left { position: static; }
}

@media (max-width: 520px) {
  .faq-wrapper   { padding: 48px 0 56px; }
  .faq-inner     { padding: 0 20px; }
  .faq-heading   { font-size: 22px; }
  .faq-question-text { font-size: 14px; }
}
